{
  "path": "supabase/functions/weather/index.ts",
  "contents": "import "jsr:@supabase/functions-js/edge-runtime.d.ts"

const WEATHER_API_BASE = "https://api.weatherapi.com/v1/current.json"
const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders })
  }

  if (req.method !== "GET") {
    return new Response(JSON.stringify({ error: "Method not allowed" }), {
      status: 405,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    })
  }

  const apiKey = Deno.env.get("WEATHER_API_KEY")
  if (!apiKey) {
    console.error("WEATHER_API_KEY is not configured")
    return new Response(JSON.stringify({ error: "Weather service is not configured" }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    })
  }

  const incomingUrl = new URL(req.url)
  const weatherUrl = new URL(WEATHER_API_BASE)
  for (const [name, value] of incomingUrl.searchParams) {
    // Never allow a caller to override or discover the server-side credential.
    if (name !== "key" && name !== "apiKey") weatherUrl.searchParams.append(name, value)
  }
  weatherUrl.searchParams.set("key", apiKey)

  try {
    const response = await fetch(weatherUrl)
    const body = await response.arrayBuffer()
    return new Response(body, {
      status: response.status,
      headers: {
        ...corsHeaders,
        "Content-Type": response.headers.get("content-type") ?? "application/json",
      },
    })
  } catch (error) {
    console.error("Weather API request failed", error)
    return new Response(JSON.stringify({ error: "Unable to reach weather service" }), {
      status: 502,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    })
  }
})
"
}

